  results.push({ id: c.id, falsifies: c.falsifies, passed: failures.length === 0, failures });
  console.log(`${failures.length ? 'FAIL' : 'ok  '} ${c.id} [${c.falsifies}]`);
  for (const f of failures) console.log(`       ${f}`);
}

