cat > src/db.ts <<'E'
import { Database } from 'bun:sqlite';
import { readFileSync } from 'node:fs';

export function openDb(path: string, schemaPath: string): Database {
  const db = new Database(path);
  db.exec('PRAGMA foreign_keys = ON;');
  if (path !== ':memory:') db.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;');
  db.exec(readFileSync(schemaPath, 'utf8'));
  return db;
}
E
cat > src/index.ts <<'E'
import { openDb } from './db.ts';
import { createApp } from './app.ts';

const db = openDb(process.env.DB_PATH ?? ':memory:', process.env.SCHEMA_PATH ?? new URL('../../../spec/schema.sql', import.meta.url).pathname);
const app = createApp(db);
const server = Bun.serve({
  port: Number(process.env.PORT ?? 3000),
  maxRequestBodySize: 64 * 1024 * 1024,
  fetch: (req) => app(req),
});
console.log(`team-notes (bun) listening on ${server.port}`);
