  app(new Request('http://x' + path, {
    method, body,
    headers: { ...(who ? { authorization: `Bearer tok_${who}` } : {}), ...(body != null && !headers['content-type'] ? { 'content-type': 'application/json' } : {}), ...headers },
  }));
